using System;using System.Collections.Generic;using System.Linq;using System.Globalization;using Avalonia;using Avalonia.Controls;using Avalonia.Controls.Primitives;using Avalonia.Layout;using Avalonia.Media;using Avalonia.Interactivity;using Kreta.Core;using Kreta.Contexts;public class ErtekelesiSzempontokView : IEvolView{    private ITeacherContext? _context;    private ListBox? _criteriaListBox;    private ComboBox? _subjectComboBox;    private TextBox? _nameTextBox;    private TextBox? _descriptionTextBox;    private TextBlock? _statusTextBlock;    private Button? _saveButton;    private Button? _deleteButton;    private Button? _newButton;    private StackPanel? _editPanel;    private List<GenericRecord>? _criteria;    private List<Subject>? _subjects;    private GenericRecord? _selectedCriterion;    private const string EntityType = "EvaluationCriterion";    public new string Name => "Értékelési Szempontok";    public string Description => "Értékelési szempontok kezelése tantárgyanként.";    public ErtekelesiSzempontokView() { }    public ErtekelesiSzempontokView(ITeacherContext context)    {        _context = context;    }    public Control CreateView()    {        var mainPanel = new StackPanel        {            Orientation = Orientation.Vertical,            Spacing = 10,            Margin = new Thickness(10)        };        _statusTextBlock = new TextBlock { Margin = new Thickness(0, 0, 0, 10), IsVisible = false };        _criteriaListBox = new ListBox { MaxHeight = 200 };        _criteriaListBox.SelectionChanged += CriteriaListBox_SelectionChanged;        _editPanel = new StackPanel        {            Orientation = Orientation.Vertical,            Spacing = 10,            IsVisible = false        };        _subjectComboBox = new ComboBox { PlaceholderText = "Tantárgy" };        _nameTextBox = new TextBox { PlaceholderText = "Szempont neve" };        _descriptionTextBox = new TextBox { PlaceholderText = "Leírás", MinHeight = 80, TextWrapping = TextWrapping.Wrap, AcceptsReturn = true };        var buttonPanel = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 10 };        _saveButton = new Button { Content = "Mentés" };        _saveButton.Click += SaveButton_Click;        _deleteButton = new Button { Content = "Törlés" };        _deleteButton.Click += DeleteButton_Click;        buttonPanel.Children.Add(_saveButton);        buttonPanel.Children.Add(_deleteButton);        _editPanel.Children.Add(_subjectComboBox);        _editPanel.Children.Add(_nameTextBox);        _editPanel.Children.Add(_descriptionTextBox);        _editPanel.Children.Add(buttonPanel);        _newButton = new Button { Content = "Új szempont felvétele", HorizontalAlignment = HorizontalAlignment.Left };        _newButton.Click += NewButton_Click;        mainPanel.Children.Add(new TextBlock { Text = "Értékelési Szempontok", FontSize = 20, FontWeight = FontWeight.Bold });        mainPanel.Children.Add(_statusTextBlock);        mainPanel.Children.Add(_newButton);        mainPanel.Children.Add(new Separator { Margin = new Thickness(0, 10) });        mainPanel.Children.Add(new TextBlock { Text = "Meglévő szempontok:" });        mainPanel.Children.Add(_criteriaListBox);        mainPanel.Children.Add(_editPanel);        LoadInitialData();        return mainPanel;    }    private void LoadInitialData()    {        if (_context == null || _criteriaListBox == null || _subjectComboBox == null) return;        try        {            _subjects = _context.GetAllSubjects();            if (_subjects != null)            {                _subjectComboBox.ItemsSource = _subjects.Select(s => s.Name).ToList();            }            _criteria = _context.QueryEntities(EntityType);            if (_criteria != null)            {                _criteriaListBox.ItemsSource = _criteria.Select(c =>                     c.Data.TryGetValue("CriterionName", out var name) ? name : "Névtelen szempont"                ).ToList();            }        }        catch (Exception ex)        {            SetStatusMessage($"Hiba az adatok betöltése közben: {ex.Message}", true);        }    }    private void CriteriaListBox_SelectionChanged(object? sender, SelectionChangedEventArgs e)    {        if (_criteriaListBox == null || _criteriaListBox.SelectedItem == null || _criteria == null || _editPanel == null || _subjects == null) return;        int selectedIndex = _criteriaListBox.SelectedIndex;        if (selectedIndex >= 0 && selectedIndex < _criteria.Count)        {            _selectedCriterion = _criteria[selectedIndex];            _editPanel.IsVisible = true;            if (_nameTextBox != null)                _nameTextBox.Text = _selectedCriterion.Data.GetValueOrDefault("CriterionName", "");            if (_descriptionTextBox != null)                _descriptionTextBox.Text = _selectedCriterion.Data.GetValueOrDefault("CriterionDescription", "");            if (_subjectComboBox != null && _selectedCriterion.Data.TryGetValue("SubjectId", out var subjectIdStr) && int.TryParse(subjectIdStr, out int subjectId))            {                var subject = _subjects.FirstOrDefault(s => s.Id == subjectId);                if (subject != null)                {                    _subjectComboBox.SelectedItem = subject.Name;                }            }        }        else        {            _selectedCriterion = null;            _editPanel.IsVisible = false;        }    }    private void NewButton_Click(object? sender, RoutedEventArgs e)    {        _selectedCriterion = null;        if (_criteriaListBox != null) _criteriaListBox.SelectedItem = null;        if (_nameTextBox != null) _nameTextBox.Text = "";        if (_descriptionTextBox != null) _descriptionTextBox.Text = "";        if (_subjectComboBox != null) _subjectComboBox.SelectedIndex = -1;        if (_editPanel != null) _editPanel.IsVisible = true;    }    private void SaveButton_Click(object? sender, RoutedEventArgs e)    {        if (_context == null || _nameTextBox == null || _descriptionTextBox == null || _subjectComboBox == null || _subjects == null) return;        if (string.IsNullOrWhiteSpace(_nameTextBox.Text) || _subjectComboBox.SelectedItem == null)        {            SetStatusMessage("A szempont neve és a tantárgy megadása kötelező.", true);            return;        }        var selectedSubject = _subjects.FirstOrDefault(s => s.Name == (string)_subjectComboBox.SelectedItem);        if (selectedSubject == null)        {            SetStatusMessage("Érvénytelen tantárgy kiválasztva.", true);            return;        }        var data = new Dictionary<string, string>        {            { "CriterionName", _nameTextBox.Text },            { "CriterionDescription", _descriptionTextBox.Text ?? "" },            { "SubjectId", selectedSubject.Id.ToString(CultureInfo.InvariantCulture) }        };        try        {            _context.SaveEntity(EntityType, data, _selectedCriterion?.Id);            SetStatusMessage("Mentés sikeres!", false);            LoadInitialData();            NewButton_Click(null, null);        }        catch (Exception ex)        {            SetStatusMessage($"Hiba mentés közben: {ex.Message}", true);        }    }    private void DeleteButton_Click(object? sender, RoutedEventArgs e)    {        if (_context == null || _selectedCriterion == null)        {            SetStatusMessage("Nincs szempont kiválasztva a törléshez.", true);            return;        }        try        {            _context.DeleteEntity(EntityType, _selectedCriterion.Id);            SetStatusMessage("Szempont sikeresen törölve.", false);            LoadInitialData();            NewButton_Click(null, null);             if (_editPanel != null) _editPanel.IsVisible = false;        }        catch (Exception ex)        {            SetStatusMessage($"Hiba a törlés során: {ex.Message}", true);        }    }    private void SetStatusMessage(string message, bool isError)    {        if (_statusTextBlock == null) return;        _statusTextBlock.Text = message;        _statusTextBlock.Foreground = isError ? Brushes.Red : Brushes.Green;        _statusTextBlock.IsVisible = true;    }}